llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Imipramine, a lipophilic tertiary-amine tricyclic antidepressant, has absolute oral bioavailability of 29–77% in healthy subjects, with typical values around 40–50%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Desipramine, the secondary-amine analogue of imipramine, has a mean absolute oral bioavailability of 38% in healthy volunteers after a 50 mg oral dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Amitriptyline, a tricyclic antidepressant with a dimethylaminopropylidene side chain, shows absolute oral bioavailability of 47.7 ± 11% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Nortriptyline, a secondary-amine tricyclic antidepressant, has absolute oral bioavailability of 46–70% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Fentanyl, a lipophilic basic amine with aromatic groups, has absolute oral bioavailability of 31% in healthy volunteers, supporting F ≥ 20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "S-Desethyloxybutynin, a tertiary-amine metabolite with aromatic and alicyclic features, has oral bioavailability of 78 ± 16% in healthy adults, supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Rotigotine, an aminotetralin dopamine agonist, has low oral bioavailability in humans and is limited to non-oral routes; this is a structurally related low-F example, but its phenolic group and different ionization profile reduce transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic basic diamine containing an indane and phenyl group. Most transferable experimental analogues—tricyclic antidepressants, fentanyl, and related lipophilic amines—show absolute oral bioavailability above 30%, strongly supporting F ≥ 20%. The main low-F analogue, rotigotine, has a phenol that drives extensive first-pass metabolism and is structurally less similar. Overall, the evidence favors high oral bioavailability at the 20% threshold.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule.",
    "Morgan similarities to the evidence molecules are modest (0.23–0.28), limiting precise transferability.",
    "The rotigotine low-F example shows that some related aminotetralin scaffolds can have poor oral bioavailability, so experimental confirmation is needed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

